#!/usr/bin/env node
/**
 * Generates everything in `web/lib/generated/`, which is gitignored and rebuilt
 * on every `npm run dev` and `npm run build` (including on Vercel):
 *
 *   lexicon-core.js    <- lib/demo-entry.ts, esbuild, browser ESM. The REAL
 *                         matcher from ../src/core, so the page's live demo and
 *                         the CLI cannot drift apart.
 *   lexicon-core.d.ts  <- hand-written types for the above, so `tsc --noEmit`
 *                         and the Next build stay fully typed.
 *   demo-lexicon.json  <- the four starter packs (155 terms) plus the Ashlr.AI
 *                         entry from examples/lexicon.example.yaml, parsed from
 *                         the same YAML the CLI ships. Parsed here rather than
 *                         in the browser so the bundle needs no YAML parser.
 *   brand-icons.json   <- monochrome SVG path data from simple-icons (CC0) for
 *                         the "works with" wall. See docs/LANDING.md for the
 *                         trademark policy: no Apple logo, no recolouring.
 *
 * Mirrors scripts/build-site.mjs at the repo root, including its guard that no
 * `node:` builtin may survive into a browser bundle.
 */
import { build } from 'esbuild';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parse as parseYaml } from 'yaml';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repo = resolve(web, '..');
const outdir = resolve(web, 'lib/generated');

/*
 * This script reads ../src/core, ../packs and ../examples, which exist when you
 * run it inside the Lexicon repository but not when `vercel --cwd web` uploads
 * this directory on its own. In that case the artifacts have already been
 * generated locally and uploaded (see .vercelignore), so keep them: a rebuild
 * is impossible and unnecessary. If neither the sources nor the artifacts are
 * present, fail loudly rather than serve a page whose demo cannot work.
 */
const haveSources = existsSync(resolve(repo, 'src/core/matcher.ts'));
const haveArtifacts = ['lexicon-core.js', 'lexicon-core.d.ts', 'demo-lexicon.json', 'brand-icons.json']
  .every((f) => existsSync(resolve(outdir, f)));

if (!haveSources) {
  if (!haveArtifacts) {
    throw new Error(
      'Neither ../src/core nor a prebuilt lib/generated is present. Run this script ' +
        'from inside the Lexicon repository first, then deploy.',
    );
  }
  process.stdout.write('lib/generated: using the prebuilt bundle (repository sources not present)\n');
  process.exit(0);
}
mkdirSync(outdir, { recursive: true });

/* ---------------------------------------------------------------- core bundle */

// esbuild resolves a bare import from the importing file upward, so a matcher.ts
// under <repo>/src/core looks in <repo>/node_modules and never in web/node_modules.
// On Vercel only web/ is installed (rootDirectory is web), so point esbuild at both.
const nodePaths = [resolve(web, 'node_modules'), resolve(repo, 'node_modules')];

await build({
  absWorkingDir: repo,
  nodePaths,
  entryPoints: [resolve(web, 'lib/demo-entry.ts')],
  outfile: resolve(outdir, 'lexicon-core.js'),
  bundle: true,
  platform: 'browser',
  format: 'esm',
  target: 'es2022',
  minify: true,
  sourcemap: false,
  legalComments: 'none',
  logLevel: 'warning',
});

const bundle = readFileSync(resolve(outdir, 'lexicon-core.js'), 'utf8');
const builtins = bundle.match(/["']node:[a-z_/]+["']/g);
if (builtins) {
  throw new Error(
    `demo bundle imports Node builtins (${[...new Set(builtins)].join(', ')}); ` +
      'only browser-safe modules may be re-exported from lib/demo-entry.ts',
  );
}

writeFileSync(
  resolve(outdir, 'lexicon-core.d.ts'),
  `// Generated by scripts/build-demo-bundle.mjs. Do not edit.
export type TermCategory = 'brand' | 'person' | 'product' | 'acronym' | 'identifier' | 'place' | 'other';
export type MatchReason = 'alias' | 'phonetic' | 'fuzzy';
export interface Term {
  canonical: string;
  aliases: string[];
  phonetic?: string;
  category?: TermCategory;
  notes?: string;
  never?: string[];
  caseSensitive?: boolean;
}
export interface Lexicon { version: 1; terms: Term[]; settings?: Record<string, unknown> }
export interface Replacement {
  start: number; end: number; original: string; replacement: string;
  canonical: string; reason: MatchReason; confidence: number;
}
export interface NormalizeResult {
  input: string; output: string; replacements: Replacement[]; changed: boolean;
}
export declare const DEFAULT_MIN_CONFIDENCE: number;
export declare function normalize(text: string, lexicon: Lexicon, opts?: {
  minConfidence?: number; phonetic?: boolean; fuzzy?: boolean; skipCode?: boolean; dryRun?: boolean;
}): NormalizeResult;
export declare function suggestAliases(canonical: string): string[];
`,
);

/* --------------------------------------------------------------- demo lexicon */

/*
 * The demo lexicon is validated here, on the server, with the project's real
 * `parseLexicon` (zod). Doing it at build time rather than in the browser keeps
 * zod -- 445 KB of a 486 KB bundle -- off the page entirely, and still fails the
 * build if a pack ever stops matching the schema.
 */
const validatorPath = resolve(outdir, '.validate-lexicon.mjs');
await build({
  absWorkingDir: repo,
  nodePaths,
  stdin: {
    contents: "export { parseLexicon } from './src/core/schema.js';",
    resolveDir: repo,
    loader: 'ts',
  },
  outfile: validatorPath,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node20',
  logLevel: 'warning',
});
const { parseLexicon } = await import(pathToFileURL(validatorPath).href);

const packDir = resolve(repo, 'packs');
const packFiles = readdirSync(packDir).filter((f) => f.endsWith('.yaml')).sort();
const packs = [];
const terms = [];

// The Ashlr.AI entry is the example file's headline term and is in no pack (a
// pack carrying one company's brand would help nobody). The demo needs it
// because "Ashler" is the canonical illustration of the whole problem.
const example = parseYaml(readFileSync(resolve(repo, 'examples/lexicon.example.yaml'), 'utf8'));
const ashlr = example.terms.find((t) => t.canonical === 'Ashlr.AI');
if (!ashlr) throw new Error('examples/lexicon.example.yaml no longer defines Ashlr.AI');
terms.push(ashlr);

for (const file of packFiles) {
  const doc = parseYaml(readFileSync(resolve(packDir, file), 'utf8'));
  const list = Array.isArray(doc.terms) ? doc.terms : [];
  if (list.length === 0) throw new Error(`pack ${file} has no terms`);
  packs.push({ id: file.replace(/\.yaml$/, ''), title: doc.title ?? file, count: list.length });
  terms.push(...list);
}

const lexicon = parseLexicon({ version: 1, terms });
const packTotal = packs.reduce((n, p) => n + p.count, 0);

// The headline demo sentence is load-bearing: it is printed on the page as a
// promise about what the matcher does. Prove it here so a pack edit that breaks
// it fails the build instead of shipping a lie.
const { normalize } = await import(pathToFileURL(resolve(outdir, 'lexicon-core.js')).href);
const PROOF_IN = 'ping ashler about the cuban eats rollout on versal';
const PROOF_OUT = 'ping Ashlr.AI about the Kubernetes rollout on Vercel';
const proof = normalize(PROOF_IN, lexicon);
if (proof.output !== PROOF_OUT) {
  throw new Error(
    `demo sentence regressed.\n  in:       ${PROOF_IN}\n  expected: ${PROOF_OUT}\n  got:      ${proof.output}`,
  );
}

writeFileSync(
  resolve(outdir, 'demo-lexicon.json'),
  JSON.stringify({ lexicon, packs, packTotal }),
);
rmSync(validatorPath, { force: true });

/* ---------------------------------------------------------------- brand icons */

/**
 * simple-icons slugs for the "works with" wall. The SVG paths are CC0; the
 * trademarks are not. Rendered monochrome in the page's neutral foreground,
 * never in the accent colour, never locked up with a Lexicon mark.
 *
 * Deliberately absent: Apple. Apple's Identity Guidelines forbid using the
 * Apple logo to indicate compatibility, so macOS, Mac and iPhone are set as
 * words in the page's own type. Also absent: Wispr Flow and Superwhisper,
 * which simple-icons does not carry, so they are set as words too.
 */
const slugs = [
  'claudecode', 'claude', 'anthropic', 'googlegemini', 'cursor', 'windsurf',
  'perplexity', 'poe', 'googlechrome', 'firefoxbrowser', 'deepgram',
  'googlecloud', 'github',
];
const icons = {};
const simpleIcons = await import('simple-icons');
for (const slug of slugs) {
  const icon = simpleIcons[`si${slug.charAt(0).toUpperCase()}${slug.slice(1)}`];
  // A slug simple-icons has renamed or -- more often -- removed at the brand's
  // own request is skipped rather than shipped as a broken or unlicensed glyph.
  // The wall falls back to a wordmark set in our type, which is exactly what we
  // want for a brand that asked not to be reproduced.
  if (icon?.path) icons[slug] = { title: icon.title, path: icon.path };
}
writeFileSync(resolve(outdir, 'brand-icons.json'), JSON.stringify(icons));

const kb = (n) => (n / 1024).toFixed(1);
process.stdout.write(
  `lib/generated/lexicon-core.js   ${kb(bundle.length)} KB\n` +
    `lib/generated/demo-lexicon.json ${terms.length} terms (${packTotal} from ${packs.length} packs + Ashlr.AI)\n` +
    `lib/generated/brand-icons.json  ${Object.keys(icons).length}/${slugs.length} marks\n`,
);
